import * as THREE from 'three';

/**
 * Build a parametric ring as a single THREE.Group.
 *
 * Children:
 *   - "band": TorusGeometry ring lying in the XY plane (hole facing +/-Z),
 *     centered on the origin.
 *   - "gem": OctahedronGeometry seated on top of the band.
 *   - "prong-0" .. "prong-N-1": thin cylinders spaced evenly around the gem,
 *     holding it in place.
 *
 * Every call recomputes all geometry from the given parameters -- nothing is
 * reused or scaled from a previous build.
 */
export function createRing({
  bandRadius = 10,
  bandThickness = 1,
  gemRadius = 2,
  prongCount = 4,
} = {}) {
  const group = new THREE.Group();
  group.name = 'ring';

  // --- Band -------------------------------------------------------------
  const bandGeometry = new THREE.TorusGeometry(
    bandRadius,
    bandThickness,
    24,
    96
  );
  const band = new THREE.Mesh(
    bandGeometry,
    new THREE.MeshStandardMaterial({ color: 0xd4af37, metalness: 0.9, roughness: 0.25 })
  );
  band.name = 'band';
  group.add(band);

  // Top surface of the band along +Y where the gem is seated.
  const bandTopY = bandRadius + bandThickness;

  // --- Gem --------------------------------------------------------------
  // Seat the gem so its lower tip rests on the top of the band.
  const gemGeometry = new THREE.OctahedronGeometry(gemRadius);
  const gem = new THREE.Mesh(
    gemGeometry,
    new THREE.MeshStandardMaterial({ color: 0x66ccff, metalness: 0.1, roughness: 0.05 })
  );
  gem.name = 'gem';
  gem.position.set(0, bandTopY + gemRadius, 0);
  group.add(gem);

  // --- Prongs -----------------------------------------------------------
  const prongRadius = Math.min(gemRadius * 0.12, bandThickness * 0.35);
  const prongHeight = gemRadius * 2;
  const prongGeometry = new THREE.CylinderGeometry(prongRadius, prongRadius, prongHeight, 8);

  for (let i = 0; i < prongCount; i++) {
    const prong = new THREE.Mesh(
      prongGeometry,
      new THREE.MeshStandardMaterial({ color: 0xd4af37, metalness: 0.9, roughness: 0.25 })
    );
    prong.name = `prong-${i}`;

    // Evenly spaced around the gem's equator, in the plane perpendicular
    // to the band axis (the XZ plane at the gem's height).
    const angle = (i / prongCount) * Math.PI * 2;
    prong.position.set(
      Math.cos(angle) * gemRadius,
      gem.position.y,
      Math.sin(angle) * gemRadius
    );

    group.add(prong);
  }

  return group;
}

