import { describe, it, expect } from 'vitest';
import * as THREE from 'three';
import { createRing } from '../src/ring.js';

describe('createRing', () => {
  it('creates a group named children band, gem and 4 prongs by default', () => {
    const ring = createRing();

    const names = ring.children.map((c) => c.name);
    expect(names).toContain('band');
    expect(names).toContain('gem');
    const prongs = ring.children.filter((c) => /^prong-\d+$/.test(c.name));
    expect(prongs).toHaveLength(4);
  });

  it('yields prongCount prongs (6 requested -> 6 built)', () => {
    const ring = createRing({ prongCount: 6 });

    const prongs = ring.children
      .filter((c) => /^prong-\d+$/.test(c.name))
      .sort((a, b) => a.name.localeCompare(b.name));
    expect(prongs).toHaveLength(6);
    // names are exactly prong-0 .. prong-5
    prongs.forEach((p, i) => expect(p.name).toBe(`prong-${i}`));
  });

  it('doubling bandRadius doubles the band x-extent within 5%', () => {
    const params = { bandRadius: 10, bandThickness: 1 };
    const ring1 = createRing(params);
    const box1 = new THREE.Box3().setFromObject(ring1.getObjectByName('band'));
    const extent1 = box1.max.x - box1.min.x;

    const ring2 = createRing({ ...params, bandRadius: 20 });
    const box2 = new THREE.Box3().setFromObject(ring2.getObjectByName('band'));
    const extent2 = box2.max.x - box2.min.x;

    const ratio = extent2 / extent1;
    expect(Math.abs(ratio - 2)).toBeLessThanOrEqual(0.05 * 2);
  });

  it('seats the gem above the top of the band', () => {
    const bandRadius = 10;
    const bandThickness = 1;
    const ring = createRing({ bandRadius, bandThickness, gemRadius: 2 });
    ring.updateMatrixWorld(true);

    const gemWorld = new THREE.Vector3();
    ring.getObjectByName('gem').getWorldPosition(gemWorld);

    const bandTopY = bandRadius + bandThickness;
    expect(gemWorld.y).toBeGreaterThan(bandTopY);
  });

  it("gem bounding sphere radius tracks gemRadius", () => {
    for (const gemRadius of [1.5, 2.5]) {
      const ring = createRing({ gemRadius });
      const gem = ring.getObjectByName('gem');
      gem.geometry.computeBoundingSphere();
      expect(gem.geometry.boundingSphere.radius).toBeCloseTo(gemRadius, 6);
    }
  });

  it('recomputes geometry instead of scaling leftovers', () => {
    const small = createRing({ bandRadius: 5, bandThickness: 0.5, gemRadius: 1 });
    const large = createRing({ bandRadius: 10, bandThickness: 0.5, gemRadius: 1 });

    const smallBand = small.getObjectByName('band');
    const largeBand = large.getObjectByName('band');

    // Distinct geometry objects, each with correct intrinsic dimensions.
    expect(smallBand.geometry).not.toBe(largeBand.geometry);
    expect(largeBand.geometry.parameters.radius).toBe(10);
    expect(smallBand.geometry.parameters.radius).toBe(5);

    // No scale hacks anywhere in the hierarchy.
    large.traverse((o) => {
      if (o.isMesh) {
        expect(o.scale.x).toBe(1);
        expect(o.scale.y).toBe(1);
        expect(o.scale.z).toBe(1);
      }
    });
  });
});

